  typedef PathRequestT NativeTableType;
  typedef PathRequestBuilder Builder;
  enum FlatBuffersVTableOffset FLATBUFFERS_VTABLE_UNDERLYING_TYPE {
    VT_REQUEST_ID = 4,
    VT_START = 6,
    VT_END = 8,
    VT_MOVE_TYPE = 10,
    VT_GOAL_RADIUS = 12
  };
  uint32_t request_id() const {
    return GetField<uint32_t>(VT_REQUEST_ID, 0);
  }
  const SpringWeb::Vec3 *start() const {
    return GetStruct<const SpringWeb::Vec3 *>(VT_START);
  }
  const SpringWeb::Vec3 *end() const {
    return GetStruct<const SpringWeb::Vec3 *>(VT_END);
  }
  /// Index into the server's MoveDefHandler (`MoveDef::pathType`).
  /// Different unit types take different routes — a kbot can climb
  /// hills a tank can't.
  uint32_t move_type() const {
    return GetField<uint32_t>(VT_MOVE_TYPE, 0);
  }
  /// Search radius around `end` — if the exact end is unreachable,
  /// accept any reachable point within this distance. Spring's
  /// default is 8.0 elmos.
  float goal_radius() const {
    return GetField<float>(VT_GOAL_RADIUS, 0.0f);
  }
  bool Verify(::flatbuffers::Verifier &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyField<uint32_t>(verifier, VT_REQUEST_ID, 4) &&
           VerifyField<SpringWeb::Vec3>(verifier, VT_START, 4) &&
           VerifyField<SpringWeb::Vec3>(verifier, VT_END, 4) &&
           VerifyField<uint32_t>(verifier, VT_MOVE_TYPE, 4) &&
           VerifyField<float>(verifier, VT_GOAL_RADIUS, 4) &&
           verifier.EndTable();
  }
  PathRequestT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(PathRequestT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<PathRequest> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const PathRequestT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
