  const SpringWeb::Vec3 *within_radius_center() const {
    return GetStruct<const SpringWeb::Vec3 *>(VT_WITHIN_RADIUS_CENTER);
  }
  float within_radius_radius() const {
    return GetField<float>(VT_WITHIN_RADIUS_RADIUS, 0.0f);
  }
  /// "Must be outside this circle" filter on the squad's mid-position.
  const SpringWeb::Vec3 *outside_radius_center() const {
    return GetStruct<const SpringWeb::Vec3 *>(VT_OUTSIDE_RADIUS_CENTER);
  }
  float outside_radius_radius() const {
    return GetField<float>(VT_OUTSIDE_RADIUS_RADIUS, 0.0f);
  }
  /// Minimum aggregate squad strength (HP × count). 0 = no minimum.
  float min_strength() const {
    return GetField<float>(VT_MIN_STRENGTH, 0.0f);
  }
  /// Capability tags the squad must have, e.g. "build", "repair",
  /// "scout". Resolution against unit defs is server-side and may be
