  enum FlatBuffersVTableOffset FLATBUFFERS_VTABLE_UNDERLYING_TYPE {
    VT_BASE_COLOR = 4,
    VT_SURFACE_COLOR = 6,
    VT_MIN_COLOR = 8,
    VT_SURFACE_ALPHA = 10,
    VT_DAMAGE = 12,
    VT_VOID_WATER = 14
  };
  const ::flatbuffers::Vector<float> *base_color() const {
    return GetPointer<const ::flatbuffers::Vector<float> *>(VT_BASE_COLOR);
  }
  const ::flatbuffers::Vector<float> *surface_color() const {
    return GetPointer<const ::flatbuffers::Vector<float> *>(VT_SURFACE_COLOR);
  }
  const ::flatbuffers::Vector<float> *min_color() const {
    return GetPointer<const ::flatbuffers::Vector<float> *>(VT_MIN_COLOR);
  }
  float surface_alpha() const {
    return GetField<float>(VT_SURFACE_ALPHA, 0.0f);
  }
  float damage() const {
    return GetField<float>(VT_DAMAGE, 0.0f);
  }
  bool void_water() const {
    return GetField<uint8_t>(VT_VOID_WATER, 0) != 0;
  }
  bool Verify(::flatbuffers::Verifier &verifier) const {
    return VerifyTableStart(verifier) &&
           VerifyOffset(verifier, VT_BASE_COLOR) &&
           verifier.VerifyVector(base_color()) &&
           VerifyOffset(verifier, VT_SURFACE_COLOR) &&
           verifier.VerifyVector(surface_color()) &&
           VerifyOffset(verifier, VT_MIN_COLOR) &&
           verifier.VerifyVector(min_color()) &&
           VerifyField<float>(verifier, VT_SURFACE_ALPHA, 4) &&
           VerifyField<float>(verifier, VT_DAMAGE, 4) &&
           VerifyField<uint8_t>(verifier, VT_VOID_WATER, 1) &&
           verifier.EndTable();
  }
  MapWaterT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
